import { Injectable } from '@nestjs/common';
import { type XrayNode, XrayNodeClient, XrayNodeError } from './xray-node.client';

/** Reality inbound params of a node, generated by xray-server-instance on first start. */
export interface RealityParams {
  publicKey: string;
  serverName: string;
  port: number;
  shortId: string;
}

/** Inbound tag and API address are fixed in xray-server-instance's config. */
const INBOUND_TAG = 'vless-in';
const XRAY_API = '127.0.0.1:10085';
const USERS_DIR = '/xray/data/users';
const PARAMS_TTL_MS = 60 * 60 * 1000;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/** Manages VLESS clients on xray-server-instance nodes. */
@Injectable()
export class XrayService {
  private readonly paramsCache = new Map<string, { params: RealityParams; fetchedAt: number }>();

  constructor(private readonly client: XrayNodeClient) {}

  /**
   * Adds (or re-adds) a client. The user file survives container restarts:
   * xray-server-instance re-imports `/xray/data/users/*.json` on start.
   */
  addClient(node: XrayNode, clientId: string): Promise<void> {
    return this.addClients(node, [clientId]);
  }

  /** Adds several clients in one request to the node. */
  async addClients(node: XrayNode, clientIds: string[]): Promise<void> {
    clientIds.forEach(assertUuid);
    if (clientIds.length === 0) return;
    const { port } = await this.getRealityParams(node);
    const commands = [`mkdir -p ${USERS_DIR}`];
    for (const clientId of clientIds) {
      const file = `${USERS_DIR}/${clientId}.json`;
      const config = JSON.stringify({
        inbounds: [
          {
            tag: INBOUND_TAG,
            listen: '0.0.0.0',
            port,
            protocol: 'vless',
            settings: {
              clients: [{ id: clientId, email: clientId, flow: 'xtls-rprx-vision', level: 0 }],
              decryption: 'none',
            },
          },
        ],
      });
      // clientId is a validated UUID and config has no single quotes, so the shell quoting is safe.
      commands.push(
        `printf '%s' '${config}' > ${file}`,
        // Remove first so adding an existing client does not fail.
        rmuCommand(clientId),
        `xray api adu --server=${XRAY_API} ${file}`,
      );
    }
    await this.client.run(node, commands);
  }

  /** Removes a client; succeeds if it is already gone. */
  removeClient(node: XrayNode, clientId: string): Promise<void> {
    return this.removeClients(node, [clientId]);
  }

  /** Removes several clients in one request; missing ones are ignored. */
  async removeClients(node: XrayNode, clientIds: string[]): Promise<void> {
    clientIds.forEach(assertUuid);
    if (clientIds.length === 0) return;
    await this.client.run(
      node,
      clientIds.flatMap((id) => [rmuCommand(id), `rm -f ${USERS_DIR}/${id}.json`]),
    );
  }

  /** Client ids present on the node (by user files in `/xray/data/users`). */
  async listClients(node: XrayNode): Promise<string[]> {
    const [out] = await this.client.run(node, [`ls -1 ${USERS_DIR} 2>/dev/null || true`]);
    return (out ?? '')
      .split('\n')
      .map((line) => line.trim().replace(/\.json$/, ''))
      .filter((id) => UUID_RE.test(id));
  }

  /** Reality params of a node, cached for an hour. */
  async getRealityParams(node: XrayNode): Promise<RealityParams> {
    const cached = this.paramsCache.get(node.host);
    if (cached && Date.now() - cached.fetchedAt < PARAMS_TTL_MS) return cached.params;

    const out = await this.client.run(node, [
      'cat /xray/data/public.key',
      'cat /xray/data/server.name',
      'cat /xray/data/server.port',
      'cat /xray/data/short_id.key',
    ]);
    const [publicKey, serverName, portRaw, shortId] = out.map((v) => v.trim());
    const port = Number(portRaw);
    if (
      !publicKey ||
      !serverName ||
      !shortId ||
      !Number.isInteger(port) ||
      port < 1 ||
      port > 65535
    ) {
      throw new XrayNodeError(
        node.code,
        'bad_response',
        `invalid reality params: ${out.join('|')}`,
      );
    }
    const params = { publicKey, serverName, port, shortId };
    this.paramsCache.set(node.host, { params, fetchedAt: Date.now() });
    return params;
  }

  /** `vless://` link for a client on a node. */
  async buildVlessLink(node: XrayNode, clientId: string, label: string): Promise<string> {
    assertUuid(clientId);
    const p = await this.getRealityParams(node);
    const query = new URLSearchParams({
      encryption: 'none',
      security: 'reality',
      sni: p.serverName,
      fp: 'firefox',
      pbk: p.publicKey,
      sid: p.shortId,
      type: 'tcp',
      headerType: 'none',
      flow: 'xtls-rprx-vision',
    });
    return `vless://${clientId}@${node.host}:${p.port}?${query.toString()}#${encodeURIComponent(label)}`;
  }
}

function rmuCommand(clientId: string): string {
  return `xray api rmu --server=${XRAY_API} --tag=${INBOUND_TAG} ${clientId} >/dev/null 2>&1 || true`;
}

function assertUuid(id: string): void {
  if (!UUID_RE.test(id)) throw new Error(`Invalid xray client id: ${id}`);
}
